/// <summary>
/// One virtual bin of a store.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountBinRow
{
    str binId;
    str description;
    str locationId;
}

Method.Source:
[DataMemberAttribute('BinId')]
public str parmBinId(str _value = binId)
{
    binId = _value;
    return binId;
}

[DataMemberAttribute('Description')]
public str parmDescription(str _value = description)
{
    description = _value;
    return description;
}

[DataMemberAttribute('LocationId')]
public str parmLocationId(str _value = locationId)
{
    locationId = _value;
    return locationId;
}
